"""Hand-authored integration expectations, never generated by the compiler."""
import json
from io import BytesIO
from dataclasses import fields,is_dataclass
from collections.abc import Mapping
from PIL import Image

SPEC={'type':'bar','width':180,'height':120,'padding':20,
      'data':{'values':[{'k':'A','v':1},{'k':'B','v':3}]},'xField':'k','yField':'v'}
DSL='''vchart bar
size 180 120
padding = 20
data = {values: [{k: "A", v: 1}, {k: "B", v: 3}]}
xField = "k"
yField = "v"
'''
GEO={'type':'FeatureCollection','features':[{'type':'Feature','properties':{'name':'West'},
     'geometry':{'type':'Polygon','coordinates':[[[0,0],[0,1],[2,1],[2,0],[0,0]]]}}]}
SVG='<svg xmlns="http://www.w3.org/2000/svg" width="40" height="20" viewBox="0 0 40 20"><rect width="20" height="20" fill="#e02020"/><rect x="20" width="20" height="20" fill="#2040e0"/></svg>'

def source_json(spec):return 'vchart\n'+json.dumps(spec,ensure_ascii=True,allow_nan=False)
def resource_dsl(kind):
    if kind=='map':
        return ('vchart map\nsize 180 120\nmap = "local"\n'
                'resource map "local" = '+json.dumps(GEO)+'\n')
    return ('vchart pictogram\nsize 180 120\nsvg = "quad"\n'
            'data = {values: []}\n'
            'resource svg "quad" = '+json.dumps(SVG)+'\n')
def jsonable(value):
    if isinstance(value,Mapping):return {k:jsonable(v) for k,v in value.items()}
    if isinstance(value,(tuple,list)):return [jsonable(v) for v in value]
    if is_dataclass(value):return {f.name:jsonable(getattr(value,f.name)) for f in fields(value)}
    return value
def typed(value):return json.dumps(jsonable(value),sort_keys=True,ensure_ascii=True,allow_nan=False,separators=(',',':'))
def pixels(data):return Image.open(BytesIO(data)).convert('RGB')
def assert_ink(test,data):
    image=pixels(data)
    test.assertGreater(sum(min(p)<220 for p in image.getdata()),100)
    return image


class NoFontLibrary:
    """Patch the module binding, not the read-only native singleton's slots."""
    def __init__(self):
        from unittest.mock import Mock
        self.use=Mock(side_effect=AssertionError('Forbidden FontLibrary.use'))
    def __getattr__(self,name):raise AssertionError('Forbidden FontLibrary access: '+name)
    def __call__(self,*args,**kwargs):raise AssertionError('Forbidden FontLibrary construction')
